import{_ as n,a,c as r,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Nginx：重载后路由异常的恢复与复盘","description":"重载命令返回后，部分请求仍走旧路由，另一些请求返回 502。按证据定位原因，说明恢复步骤与验收条件。","frontmatter":{"title":"Nginx：重载后路由异常的恢复与复盘","description":"重载命令返回后，部分请求仍走旧路由，另一些请求返回 502。按证据定位原因，说明恢复步骤与验收条件。","showdocs":{"topics":[{"id":"nginx","title":"Nginx","link":"/topics/nginx/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Nginx 请求路径与维护理论","summary":"重载命令返回后，部分请求仍走旧路由，另一些请求返回 502。按证据定位原因，说明恢复步骤与验收条件。","status":"active","related":[{"title":"Nginx：403、404、502 与 504 定位","link":"/systems/nginx/plus/troubleshooting/diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"Nginx：静态站点与反向代理配置","link":"/systems/nginx/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"Nginx：静态站点与反向代理配置 · 请求行为矩阵与失败预期至实践练习与参考解答","link":"/systems/nginx/plus/practice/application-part-02","kind":"应用实践","scope":"general","audience":"general"},{"title":"Nginx：静态站点与反向代理配置 · 文件、依赖与隔离目录至可选上游的完整源码","link":"/systems/nginx/plus/practice/application-part-01","kind":"应用实践","scope":"general","audience":"general"},{"title":"Nginx：安装前提、配置层级与请求入口","link":"/systems/nginx/base/basic/start","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"Nginx：403、404、502 与 504 定位","link":"/systems/nginx/plus/troubleshooting/diagnostics"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Nginx：403、404、502 与 504 定位","link":"/systems/nginx/plus/troubleshooting/diagnostics"},"next":false},"headers":[],"relativePath":"systems/nginx/pro/review/review.md","filePath":"systems/nginx/pro/review/review.md"}'),i={name:"systems/nginx/pro/review/review.md"};function o(s,e,l,p,c,d){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="nginx-重载后路由异常的恢复与复盘" tabindex="-1">Nginx：重载后路由异常的恢复与复盘 <a class="header-anchor" href="#nginx-重载后路由异常的恢复与复盘" aria-label="Permalink to &quot;Nginx：重载后路由异常的恢复与复盘&quot;">​</a></h1><p>以下演练将Nginx 静态站与代理的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/nginx/plus/practice/application#files">配套示例</a>中的主配置、conf_prefix、Host/SNI 和上游地址。演练未执行。</p><p>前置是本系列<a href="/systems/nginx/plus/practice/application#files">完整示例</a>与<a href="/systems/nginx/plus/troubleshooting/diagnostics#sequence">排错顺序</a>。复习目标是能从请求解释结果，不能以背下一份nginx.conf替代理解。示例未执行，本篇不把理论预期记作操作验收。</p><h2 id="incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#incident-scenario}&quot;">​</a></h2><p>重载命令返回后，部分请求仍走旧路由，另一些请求返回 502。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h2 id="incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#incident-evidence}&quot;">​</a></h2><ol><li>核对运行实例的 master PID、启动参数与配置前缀，确认检查和重载针对同一个实例。</li><li>查看错误日志与 worker 代际，判断新配置是否被接纳；旧连接在平滑退出期间仍可能由旧 worker 处理。</li><li>以固定 Host、请求路径和必要的 SNI 重现，结合 access log 的上游信息区分匹配错误、连接拒绝和上游响应。</li></ol><h2 id="incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#incident-recovery}&quot;">​</a></h2><p>恢复已验证的站点配置，针对同一实例检查后再重载；若上游不可用，按发布方案恢复上游或切换已验证目标。不要靠反复重启掩盖配置与进程对应关系。</p><p>验收：对静态、代理、缺失路径分别验收，检查错误日志和新请求的上游目标；同时确认旧连接退出策略符合业务要求。语法通过不能替代路由验收。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://nginx.org/en/docs/control.html" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h2 id="request-review" tabindex="-1">请求路径自检表 <a class="header-anchor" href="#request-review" aria-label="Permalink to &quot;请求路径自检表 {#request-review}&quot;">​</a></h2><p>Nginx 请求推演按地址端口、server、location、路径变化、内容处理器、响应过滤、日志七项记录。每次改location、root、alias或proxy_pass，至少推演正常、缺失、边界前缀、查询串、未知Host及隐藏路径。规范化URI和原始目标要分别记录，不把原始字符串直接当文件路径。</p><p>练习：GET /api/status?mode=brief带Host lab.local，写出上游目标；再写unknown Host时目标。</p><p>参考解答：先选择8088上的lab.local，再选^~ /api/；proxy_pass带/的URI替换使上游收到/status?mode=brief，固定Host变成lab-backend。unknown Host选默认server，直接404，没有上游目标。查询串不参与location匹配，但通常仍传给后端。</p><h2 id="mechanism-review" tabindex="-1">机制辨析与参考答案 <a class="header-anchor" href="#mechanism-review" aria-label="Permalink to &quot;机制辨析与参考答案 {#mechanism-review}&quot;">​</a></h2><p>Nginx 机制复习应能区分root追加完整URI、alias替换匹配部分、try_files检查本地候选、proxy_pass转发请求。内部重定向会重新匹配，外部重定向让客户端重发。请求头proxy_set_header与响应头add_header方向不同；add_header继承、always和^~跳过正则都是需要就地检查的条件。</p><p>练习：为什么不把location /app/改成^~ /app/以“提高优先级”？</p><p>参考解答：那会跳过隐藏路径拒绝正则，可能暴露/app/下误放的隐藏文件；前缀更强不等于更安全。真正的发布边界还要求root中只有公开产物，配置、私钥、版本库与日志位于公开树外。若有明确需求使用^~，必须在对应处理链另行设计限制。</p><h2 id="operations-review" tabindex="-1">发布与故障决策 <a class="header-anchor" href="#operations-review" aria-label="Permalink to &quot;发布与故障决策 {#operations-review}&quot;">​</a></h2><p>Nginx 发布复习要能说明reload、reopen、quit的对象与影响。reload更新worker配置，reopen配合日志轮转，quit等待现有工作退出；三个操作都依赖正确PID和权限。检查通过与重载成功分别是配置与进程证据，业务路由需要独立请求证据。</p><p>练习：读超时后客户端准备重试支付请求，代理关闭重试是否已经安全？</p><p>参考解答：没有。proxy_next_upstream off只禁止Nginx自动换上游，客户端仍可能重放，原请求也可能已提交。写操作需要业务幂等键、持久化结果与查询机制；增加超时不是幂等协议，重复转发不是高可用的充分条件。</p><h2 id="acceptance" tabindex="-1">阅读验收与后续范围 <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;阅读验收与后续范围 {#acceptance}&quot;">​</a></h2><p>Nginx 理论验收包含六篇共享正文、完整同源示例、路径推演、精准查询和静态检查证据。源码语法检查不能证明Nginx指令合法，配置文本审阅不能替代nginx -t，更不能代替运行、权限、TLS和性能验证。</p><p>读者将来实操时，记录OS、Nginx包来源/版本/编译模块、Node版本、配置hash、预期和实际状态、日志来源与清理结果，失败应保留原始证据。HTTP/2/3、WebSocket、FastCGI、复杂rewrite、缓存一致性、动态服务发现、限流和生产HA属于后续专项，不冒称这个静态站和只读上游已经覆盖。旧stream端口映射是TCP代理，不能用HTTP的URI规则解释，也不是数据库访问控制方案。</p><h2 id="sources" tabindex="-1">来源与版本核对 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;来源与版本核对 {#sources}&quot;">​</a></h2><p>请求处理与指令语义以 Nginx 官方文档为依据。2026-10-17访问官方动态文档和下载页；文档包含超出教学版本族的新功能，示例只取共同指令，不凭页面更新推断安装环境支持。</p><p>对应依据：<a href="https://nginx.org/en/docs/http/request_processing.html" target="_blank" rel="noopener noreferrer">请求处理</a>、<a href="https://nginx.org/en/docs/http/ngx_http_core_module.html" target="_blank" rel="noopener noreferrer">核心路径模块</a>、<a href="https://nginx.org/en/docs/http/ngx_http_proxy_module.html" target="_blank" rel="noopener noreferrer">代理模块</a>、<a href="https://nginx.org/en/docs/http/ngx_http_headers_module.html" target="_blank" rel="noopener noreferrer">响应头</a>、<a href="https://nginx.org/en/docs/http/ngx_http_log_module.html" target="_blank" rel="noopener noreferrer">日志</a>、<a href="https://nginx.org/en/docs/http/ngx_http_ssl_module.html" target="_blank" rel="noopener noreferrer">TLS</a>、<a href="https://nginx.org/en/docs/control.html" target="_blank" rel="noopener noreferrer">控制信号</a>、<a href="https://nginx.org/en/docs/windows.html" target="_blank" rel="noopener noreferrer">Windows边界</a>、<a href="https://nginx.org/en/download.html" target="_blank" rel="noopener noreferrer">下载与发布分支</a>。两篇旧安装和配置全文已审阅，有用信号/权限/上传/代理场景保留原URL；旧TLS协议和源不作现行推荐。</p>',30)])])}const x=n(i,[["render",o]]);export{g as __pageData,x as default};
